apply.css:
#root { --sl-background:#101a32; --sl-ink:#f3f5ff; --sl-muted:#aab9d8; --sl-accent:#83a9ff; --sl-surface:#1c2b49; --sl-border:#344a72; --sl-radius:16px; background:#101a32 !important; color:#f3f5ff !important; font-family:Arial, sans-serif !important; }
#root * { font-family:inherit !important; }
#root :is(h1,h2,h3,[data-sl-heading]) { font-family:Arial, sans-serif !important; color:#f3f5ff !important; }
#root [data-sl-muted] { color:#aab9d8 !important; }
#root [data-sl-accent] { color:#83a9ff !important; }
#root [data-sl-surface] { background:#1c2b49 !important; color:#f3f5ff !important; border-color:#344a72 !important; border-radius:16px !important; }
#root [data-sl-fill] { background:#83a9ff !important; }
